import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.containers.create({ name: "string", file_ids: ["string"], expires_after: { anchor: "last_active_at", minutes: 1 }, skills: [{ type: "skill_reference", skill_id: "string", version: "string" }], memory_limit: "1g", network_policy: { type: "disabled" } });
